def transform(grid):
    """Extend each numbered marker along its fixed ray; intersections create 4s."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = []

    # The marker-specific displacement/path. 1 follows a two-right, one-up bend.
    def path_for(r, c, color):
        if color == 1:
            return [(r, c), (r, c + 1), (r, c + 2), (r - 1, c + 2)]
        if color == 2:
            return [(r, x) for x in range(c, c - 5, -1)]
        if color == 3:
            return [(x, c) for x in range(r, r + 4)]
        if color == 6:
            return [(x, c) for x in range(r, r - 7, -1)]
        return [(r, c)]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in (1, 2, 3, 6):
                continue
            path = path_for(r, c, color)
            if not all(0 <= rr < h and 0 <= cc < w for rr, cc in path):
                continue
            rays.append((color, path))
            for rr, cc in path[1:-1]:
                out[rr][cc] = 5
            er, ec = path[-1]
            out[er][ec] = color

    # Distinct rays crossing at an interior cell produce a 4, which then
    # travels diagonally down-left to the grid edge.
    crossings = set()
    for i, (_, first) in enumerate(rays):
        first_inner = set(first[1:-1])
        for _, second in rays[i + 1:]:
            for cell in first_inner.intersection(second[1:-1]):
                crossings.add(cell)
    for r, c in crossings:
        out[r][c] = 4
        rr, cc = r + 1, c - 1
        while rr < h and cc >= 0:
            out[rr][cc] = 4
            rr += 1
            cc -= 1
    return out
